head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vKisCd = ""; // 조회조건 기업코드
scwin.vAcntclsDt = ""; // 조회조건 결산일자
/* ★Wcraft guide★
스크립트 수작업 유의사항

*/

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면이 최초 로드될때 실행되는 초기화 이벤트 (초기 데이터 조회나 컴포넌트 설정) — 화면 초기화(init)를 수행한다.
 * @returns {void}
 * @hidden N
 * @example (body ev:onpageload 바인딩으로 자동 호출)
 */
scwin.onpageload = function() {
    try {
        scwin.init();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDFIS00400_03.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 현재 로딩된 페이지가 초기화되거나 종료될때(다른 화면으로 이동하거나 페이지를 닫기전) 발생하는 이벤트 (주로 SPA(Single Page Application) 환경에서 전역 자원을 해제하거나 메모리 누수 방지).
 * @returns {void}
 * @hidden N
 * @example (body ev:onpageunload 바인딩으로 자동 호출)
 */
scwin.onpageunload = function() {

};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name search
 * @description 연결제외종속회사 조회 — 데이터셋 초기화·조회조건 체크 후 기업코드/결산일자로 목록을 조회한다.
 * @returns {Promise<void>}
 * @hidden N
 * @example await scwin.search();
 */
scwin.search = async function() {

    // 데이터셋 초기화
    scwin.initDs();

    // 조회조건 체크
    if (!scwin.chkValid()) {
        return;
    }

    dma_consNotesExSubsInfoReq.set("kisCd", vKisCd);
    dma_consNotesExSubsInfoReq.set("acntclsDt", vAcntclsDt);
    const sbmOptions = {
        id : "sbm_consNotesExSubs",
        action : "/api/listing/nice/financial/cons-notes/ex-subs",
        method : "get",
        ref : "dma_consNotesExSubsInfoReq",
        target : "dlt_consNotesExSubsListRes|append",
        gridview : "grd_ConnExcldDpndCom",
        isProcessMsg : false
    };
    const res = await await $c.sbm.executeDynamic(sbmOptions);
    dlt_consNotesExSubsListRes.setJSON(res.responseJSON.body);

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name init
 * @description 화면 초기화 — 부모창 결산일자 조회(fn_SrchAcntclsDt) 후 연결제외종속회사를 조회한다(search).
 * @returns {void}
 * @hidden N
 * @example scwin.init();
 */
scwin.init = function() {

    // 결산일자 조회
    $p.parent().frame_head.getWindow().scwin.fn_SrchAcntclsDt();
    scwin.search();

};

/**
 * @method
 * @name initDs
 * @description 데이터셋 초기화.
 * @returns {void}
 * @hidden N
 * @example scwin.initDs();
 */
scwin.initDs = function() {
    dlt_consNotesExSubsListRes.setData([]);
};

/**
 * @method
 * @name chkValid
 * @description 조회조건 유효성 체크 — 부모창에서 기업코드·결산일자를 취득해 빈값 여부를 검사한다.
 * @returns {Boolean} 조회조건이 유효하면 true
 * @hidden N
 * @example if (!scwin.chkValid()) { return; }
 */
scwin.chkValid = function() {

    vKisCd = $p.parent().frame_head.getWindow().scwin.fn_GetKisCd();
    vAcntclsDt = $p.parent().frame_head.getWindow().scwin.fn_GetAcntclsDt();

    if (vKisCd === "" || vAcntclsDt === "") {
        return false;
    }

    return true;

};

/**
 * @method
 * @name excelDownload
 * @description 엑셀파일 다운로드 — 조회된 데이터가 없으면 안내하고, 있으면 그리드를 엑셀로 다운로드한다.
 * @returns {void}
 * @hidden N
 * @example scwin.excelDownload();
 */
scwin.excelDownload = function() {

    if (dlt_consNotesExSubsListRes.getRowCount() <= 0) {
        alert("조회된 데이터가 없습니다.");
        return;
    }

    const options = {
        fileName : "연결제외종속회사" 
    };

    const infoArray = {};
    $c.data.downloadGridViewExcel(grd_ConnExcldDpndCom, options, infoArray);

};

/**
 * @method
 * @name grd_ConnExcldDpndCom_tooltipFormatter
 * @description 그리드 연결사유코드 항목 커서 위치시 설명 표시.
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} colIndex 컬럼 인덱스
 * @param {String} label 셀 표시 텍스트
 * @param {Boolean} isOverflow 셀 오버플로우 여부
 * @param {String} type 툴팁 유형
 * @returns {String} 연결사유코드 설명 텍스트(해당 컬럼이 아니면 undefined)
 * @hidden N
 * @example scwin.grd_ConnExcldDpndCom_tooltipFormatter(0, 0, "", false, "");
 */
scwin.grd_ConnExcldDpndCom_tooltipFormatter = function (rowIndex, colIndex, label, isOverflow, type) {

    if (grd_ConnExcldDpndCom.getFocusedColumnID() === "connRsnCd") {
        return $c.stf.getConnRsnCdNm1(dlt_consNotesExSubsListRes.getCellData(rowIndex, "connRsnCd"));
    }

};
